import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    points = []
    index = 1

    for _ in range(n):
        x = int(data[index])
        y = int(data[index + 1])
        points.append((x, y))
        index += 2

    midpoints = {}

    # Iterate through all pairs of points
    for i in range(n):
        for j in range(i + 1, n):
            # Calculate midpoint
            x_mid = (points[i][0] + points[j][0]) / 2
            y_mid = (points[i][1] + points[j][1]) / 2

            # Use a tuple of floats as key
            key = (x_mid, y_mid)
            midpoints[key] = midpoints.get(key, 0) + 1

    # Count parallelograms
    result = 0
    for count in midpoints.values():
        if count >= 2:
            result += count * (count - 1) // 2

    print(result)

if __name__ == "__main__":
    solve()
"}

