# We need to find the longest regular bracket sequence (substring)
# and count how many such substrings exist

s = input().strip()

if len(s) == 0:
    print("0 1")
    exit()

# dp[i] will store the length of the longest valid substring ending at index i
max_len = 0
num_max_len = 0

dp = [0] * len(s)

for i in range(len(s)):
    if s[i] == ')' and i - dp[i-1] - 1 >= 0 and s[i - dp[i-1] - 1] == '(':
        # Found a matching pair that extends a valid substring
        length = dp[i-1] + 2
        if i - dp[i-1] - 2 >= 0:
            length += dp[i - dp[i-1] - 2]
        dp[i] = length

        # Update max_len and num_max_len
        if length > max_len:
            max_len = length
            num_max_len = 1
        elif length == max_len:
            num_max_len += 1
    elif s[i] == '(':
        # No extension, reset
        dp[i] = 0

if max_len == 0:
    print("0 1")
else:
    print(f"{max_len} {num_max_len}")
"}

