import sys

def solve() -> None:
    s = sys.stdin.readline().strip()
    n = len(s)

    # Find all occurrences of "bear"
    count = 0
    for k in range(n - 3):
        if s[k] == 'b' and s[k+1] == 'e' and s[k+2] == 'a' and s[k+3] == 'r':
            # Number of valid i's = k (1-indexed, so k+1 if 0-indexed)
            # Number of valid j's = n - (k + 3) + 1 = n - k - 2
            count += (k + 1) * (n - k - 2)

    print(count)

if __name__ == "__main__":
    solve()
"}

