import math

def get_square_free_part(x):
    """Return the square-free part of x"""
    # Remove all even powers of primes
    # This works because we only care about the square-free part
    square_free = 1

    # Divide by 2 until we get an odd number
    while x % 2 == 0:
        x //= 2

    # Check for odd primes
    i = 3
    while i * i <= x:
        # Divide by i until we can't
        while x % i == 0:
            x //= i
        i += 2

    # If remaining is > 1, it's a prime factor
    if x > 1:
        square_free *= x

    return square_free

def solve():
    t = int(input())

    for _ in range(t):
        n, k = map(int, input().split())
        a = list(map(int, input().split()))

        # Get square-free parts
        square_free = [get_square_free_part(x) for x in a]

        # Greedy segment counting
        segments = 1
        current_set = {square_free[0]}

        for i in range(1, n):
            if square_free[i] in current_set:
                # Start new segment
                segments += 1
                current_set = {square_free[i]}
            else:
                # Add to current segment
                current_set.add(square_free[i])

        print(segments)

solve()
