# Function to check if a transitive tournament
# - Sorted by out-degree, check if i < j implies adj[i][j] == 1
# - Also check if all edges are the reverse
# - If neither, return the ordering

def check_transitive_and_find_cycle():
    # Sort vertices by out-degree
    out_degree = [sum(adj[i]) for i in range(n)]
    sorted_vertices = sorted(range(n), key=out_degree)

    # Check if transitive
    is_transitive = True
    for i in range(n):
        for j in range(i + 1, n):
            if out_degree[sorted_vertices[i]] > out_degree[sorted_vertices[j]]:
                if adj[sorted_vertices[i]][sorted_vertices[j]] != 1:
                    is_transitive = False
                    break
        if not is_transitive:
            break

    if is_transitive:
        # Check if it's the reverse (all edges in opposite direction)
        is_reverse = True
        for i in range(n):
            for j in range(i + 1, n):
                if adj[i][j] == 1:
                    is_reverse = False
                    break
            if not is_reverse:
                break

        if is_reverse:
            # Reverse order is also transitive, but we need to output a cycle
            # Actually, a transitive tournament has no 3-cycles, so we need to output -1
            return -1
        else:
            # Find a cycle by checking if any triple has a 3-cycle
            for i in range(n):
                for j in range(i + 1, n):
                    if adj[i][j] == 1:
                        for k in range(n):
                            if k != i and k != j and adj[j][k] == 1 and adj[k][i] == 1:
                                return [i + 1, j + 1, k + 1]
                        break
                    if not is_transitive:
                        break
                if not is_transitive:
                    break
            return -1
    else:
