from collections import defaultdict

def solve():
    n, k = map(int, input().split())
    a = list(map(int, input().split()))

    # Precompute prime factorization of k
    def prime_factors(x):
        factors = defaultdict(int)
        i = 2
        while i * i <= x:
            while x % i == 0:
                factors[i] += 1
                x //= i
            i += 1
        if x > 1:
            factors[x] += 1
        return factors

    target = prime_factors(k)

    # For each number, store its prime factorization
    num_factors = []
    for num in a:
        num_factors.append(prime_factors(num))

    result = 0

    # Try all start positions
    for l in range(n):
        # For current start, we need to maintain divisibility
        current = defaultdict(int)
        for r in range(l, n):
            # Add prime factors of a[r]
            for p, cnt in num_factors[r].items():
                current[p] += cnt
            # Check if we meet or exceed target for all primes
            valid = True
            for p, target_cnt in target.items():
                if current[p] < target_cnt:
                    valid = False
                    break
            if valid:
                result += 1

    print(result)

solve()
