s = input()

# Try to find a valid sequence
# We need to track: position, current difference
# At each step, we'll try all possible replacements for '?',
# and check if we ever hit absolute difference k before the end

def backtrack(pos, diff, path):
    if pos == n:
        if abs(diff) == k:
            return True, path
        return False, None

    # Try all possible replacements for s[pos]
    if s[pos] == '?':
        for replacement in ['W', 'L', 'D']:
            new_diff = diff
            if replacement == 'W':
                new_diff += 1
            elif replacement == 'L':
                new_diff -= 1

            # Check if this new state is valid
            # If we hit k and it's not the last position, skip
            if abs(new_diff) == k and pos < n - 1:
                continue

            # Recursively try
            valid, result = backtrack(pos + 1, new_diff, path + replacement)
            if valid:
                return True, result
    else:
        # Fixed character, just add it
        new_diff = diff
        if s[pos] == 'W':
            new_diff += 1
        elif s[pos] == 'L':
            new_diff -= 1

        # Check if we hit k before the end
        if abs(new_diff) == k and pos < n - 1:
            return False, None

        valid, result = backtrack(pos + 1, new_diff, path + s[pos])
        if valid:
            return True, result

    return False, None

valid, result = backtrack(0, 0, "")
if valid:
