import sys

# Brute-force approach for small cases

def solve_small() -> None:
    n, m = map(int, sys.stdin.readline().split())
    edges = []
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        edges.append((u, v))

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Find connected components
    visited = [False] * (n + 1)
    components = []

    for node in range(1, n + 1):
        if not visited[node]:
            stack = [node]
            visited[node] = True
            component = set()
            component.add(node)

            while stack:
                current = stack.pop()
                for neighbor in adj[current]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        component.add(neighbor)
                        stack.append(neighbor)

            components.append(component)

    # For each pair of nodes, check harmonious condition
    is_harmonious = True

    for i in range(1, n + 1):
        if not visited[i]:
            continue
        for j in range(i + 1, n + 1):
            if i in component and j in component:
                # Check if i can reach j
                if not bfs(i, j, adj):
                    continue

                # Check if i can reach all nodes between i and j
                for k in range(i + 1, j):
                    if i in component and k in component:
                        if not bfs(i, k, adj):
                            is_harmonious = False
                            print(f"Not harmonious: i={i}, j={j}, k={k}")
                            break


    print(is_harmonious)

# Breadth-first search to check connectivity
def bfs(start, end, adj):
    if start == end:
        return True

    visited = [False] * (len(adj))
    queue = [start]
    visited[start] = True

    while queue:
        current = queue.pop(0)
        for neighbor in adj[current]:
            if neighbor == end:
                return True
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)

    return False

if __name__ == "__main__":
    solve_small()
"}

