def solve():
    t = int(input())
    results = []
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))

        # Count the number of clusters of x for each possible x
        count_clusters = {}  # key: x, value: number of clusters
        for x in set(a):
            count = 0
            prev = None
            for num in a:
                if num == x:
                    if prev != x:
                        count += 1
                        prev = x
            count_clusters[x] = count

        # Find the x that minimizes operations
        min_ops = float('inf')
        for x in count_clusters:
            # Total non-x elements that are between clusters of x
            between = 0
            prev = None
            for num in a:
                if num == x:
                    if prev is not None and prev != x:
                        # There was a non-x element between clusters
                        between += 1
                    prev = x
                else:
                    prev = num
            # Number of operations = total non-x - between
            total_non_x = n - count_clusters[x]
            ops = total_non_x - between
            min_ops = min(min_ops, ops)

        results.append(str(min_ops))

    print('\n'.join(results))

solve()
