    for j in range(m):
        board[i][j] = int(board[i][j])

# We need to reach the top row (row 0)
# Starting from some column in row n-1

# k+1 must be at least 1
modulus = k + 1

max_peas = -1
col_start = -1
path = []

# Try starting from each column in the bottom row
for start_col in range(m):
    # Use BFS or dynamic programming to find max peas
    dp = [[-1] * m for _ in range(n)]
    path_map = [[None] * m for _ in range(n)]

    # Starting point
    dp[n-1][start_col] = board[n-1][start_col]

    # Fill the DP table (row-wise)
    for i in range(n-1, 0, -1):
        for j in range(m):
            if dp[i][j] == -1:
                continue

            # Move left (L) to (i-1, j-1)
            if j > 0:
                new_peas = dp[i][j] + board[i-1][j-1]
                if new_peas > dp[i-1][j-1] or dp[i-1][j-1] == -1:
                    dp[i-1][j-1] = new_peas
                    path_map[i-1][j-1] = ('L', i, j)

            # Move right (R) to (i-1, j+1)
            if j < m - 1:
                new_peas = dp[i][j] + board[i-1][j+1]
                if new_peas > dp[i-1][j+1] or dp[i-1][j+1] == -1:
                    dp[i-1][j+1] = new_peas
                    path_map[i-1][j+1] = ('R', i, j)

    # Check if we can reach row 0
    if dp[0][0] == -1:
        continue

    # Check all columns in row 0
    for end_col in range(m):
        if dp[0][end_col] == -1:
            continue

        peas = dp[0][end_col]
        if peas % modulus == 0:
            if peas > max_peas:
                max_peas = peas
                col_start = start_col + 1  # 1-indexed

                # Reconstruct path
                path = []
                i, j = 0, end_col
                while i < n - 1:
                    move, next_i, next_j = path_map[i][j]
                    if move == 'L':
                        path.append('L')
                    else:
                        path.append('R')
                    i, j = next_i, next_j

                path.reverse()

if max_peas == -1:
    print(-1)
else:
    print(max_peas)
    print(col_start)
    print(''.join(path))
