def solve():
    s = input().strip()
    t = input().strip()

    # Check if need tree: t has characters not in s or counts differ
    # Actually, we need to check if t is an anagram of any subsequence of s
    # If not, then need tree

    # Check if array: s and t are anagrams
    def is_anagram(s, t):
        return sorted(s) == sorted(t)

    # Check if automaton: t is a subsequence of s
    def is_subsequence(sub, s):
        if not sub:
            return True
        s_iter = iter(s)
        for char in sub:
            found = False
            while True:
                try:
                    if next(s_iter) == char:
                        found = True
                        break
                except StopIteration:
                    break
            if not found:
                return False
        return True

    # Check if need tree: t is not an anagram of any subsequence of s
    # Build all subsequences of s and check if any are anagrams of t
    # This is inefficient but acceptable for small size

    # Actually, we can just check if there's any character in t not in s
    # or if t has more of some character than s
    # That's sufficient for need tree
    if not is_anagram(s, t):
        # Check if need tree: t cannot be obtained by deleting some chars from s
        # This means t has characters not in s or counts differ
        t_counts = {}
        s_counts = {}
        for c in s:
            s_counts[c] = s_counts.get(c, 0) + 1
        for c in t:
            t_counts[c] = t_counts.get(c, 0) + 1

        # Check if need tree: t has characters not in s or counts differ
        need_tree = False
        for c, count in t_counts.items():
            if s_counts.get(c, 0) < count:
                need_tree = True
                break

        if need_tree:
            print("need tree")
            return

    # Check if automaton: t is a subsequence of s
    if is_subsequence(t, s):
        print("automaton")
        return

    # Check if array: s and t are anagrams
    if is_anagram(s, t):
        print("array")
        return

    # Otherwise, need both
    print("both")

solve()
