def solve():
    n, k = map(int, input().split())
    s = input()

    # DP[i][balance][has_ended] = True if position i can be reached with this state
    # balance is wins - losses
    # has_ended is whether we've already reached |balance| = k
    dp = [[[-1 for _ in range(2)] for _ in range(2 * k + 1)] for _ in range(n + 1)]
    dp[0][0][0] = 0  # At position 0, balance 0, hasn't ended

    # Reconstruct path
    path = [None] * n

    # BFS/DP approach
    for i in range(n):
        for balance in range(-k, k + 1):
            for has_ended in [0, 1]:
                if dp[i][balance + k][has_ended] == -1:
                    continue

                # Try all possible replacements
                for char in ['W', 'L', 'D']:
                    if s[i] == '?' or s[i] == char:
                        new_balance = balance
                        if char == 'W':
                            new_balance += 1
                        elif char == 'L':
                            new_balance -= 1

                        # Check if we should end
                        if abs(new_balance) == k and i == n - 1:
                            # End condition is satisfied at the last position
                            if not has_ended:
                                dp[i + 1][new_balance + k][1] = dp[i][balance + k][has_ended]
                                path[i] = char
                        elif abs(new_balance) == k and i < n - 1:
                            # Can't end before the last position
                            continue
                        else:
                            # Continue
                            dp[i + 1][new_balance + k][has_ended] = dp[i][balance + k][has_ended]
                            path[i] = char

    # Check if solution exists
    for balance in range(-k, k + 1):
        if dp[n][balance + k][1] != -1:
            result = ''.join(path)
            print(result)
            return

    print("NO")

