import sys
from collections import defaultdict

# Function to count substring occurrences
def count_substrings(s):
    n = len(s)
    substr_count = defaultdict(int)
    for i in range(n):
        for j in range(i + 1, n + 1):
            substr_count[s[i:j]] += 1
    return substr_count

# Read input
def read_input():
    data = sys.stdin.read().strip().split()
    if not data:
        return None
    n = int(data[0])
    strings = data[1:1 + n]
    return n, strings

# Function to check if a string is good
def is_good_string(s, required_substrings):
    substr_count = count_substrings(s)

    # Get all required substrings
def get_required_substrings(s, required_strings):
    required = []
    for req in required_strings:
        if req in s:
            required.append(req)
    return required

# Main function
def solve():
    n, strings = read_input()
    if n == 0:
        return

    # Try all permutations of the strings
    min_length = float('inf')
    best_string = """"""

    # Generate all permutations of the given strings
    from itertools import permutations

    for perm in permutations(strings):
        # Construct the string by concatenating
        current = ''.join(perm)

        # Check if all required strings are present
        required = get_required_substrings(current, strings)
        if set(required) != set(strings):
            continue

        # Count all substrings
        substr_count = count_substrings(current)

        # Get occurrence counts of required substrings
        required_occurrences = {req: substr_count[req] for req in strings}

        # Check if all required substrings have the same occurrence count
        if len(set(required_occurrences.values())) > 1:
            continue

        # Get the minimum occurrence count
        min_occurrence = min(required_occurrences.values())

        # Check if no other substring has higher occurrence count
        for substr, count in substr_count.items():
            if substr not in required_occurrences and count > min_occurrence:
                break
        else:
            # All required substrings have the same occurrence count
