    if not data:
        return
    nums = list(map(int, data))

    ops = []

    while True:
        # Check if all are 1
        all_one = all(n == 1 for n in nums)
        if all_one:
            break

        # Find adjacent even numbers
        found = False
        for i in range(4):
            # Check if current number and next number are even
            if i < 3:
                if nums[i] % 2 == 0 and nums[i + 1] % 2 == 0:
                    # Divide positions i+1 and i+2
                    ops.append(f"/{i + 1}")
                    nums[i] //= 2
                    nums[i + 1] //= 2
                    found = True
                    break
            else:
                # Check if last number and first number are even
