import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    moods = data[1:1+n]

    # Check for each possible regular polygon
    for d in range(3, n + 1):
        # Check if d divides n
        if n % d != 0:
            continue

        k = n // d  # step between vertices of the polygon

        # Check if every k-th knight is in good mood
        valid = True
        for i in range(d):
            if moods[i * k] != '1':
                valid = False
                break

        if valid:
            print("YES")
            return

    print("NO")

if __name__ == "__main__":
    solve()
"}

