def is_consistent(candidate, guess, bulls, cows):
    """Check if candidate is consistent with the guess"""
    target_digits = list(candidate)
    guess_digits = list(guess)

    # Count bulls (exact matches)
    bull_count = sum(1 for i in range(4) if target_digits[i] == guess_digits[i])

    # If bulls already exceed given, inconsistent
    if bull_count > bulls:
        return False

    # Count cows (digits present but in wrong positions)
    # First, create a set of remaining digits in target (excluding bulls)
    remaining_target = []
    for i in range(4):
        if target_digits[i] != guess_digits[i]:
            remaining_target.append(target_digits[i])

    # Count how many of the remaining guess digits are in remaining_target
    remaining_guess = []
    for i in range(4):
        if target_digits[i] != guess_digits[i]:
            remaining_guess.append(guess_digits[i])

    cow_count = 0
    for d in remaining_guess:
        if d in remaining_target:
            cow_count += 1
            # Remove from remaining_target to avoid double counting
            remaining_target.remove(d)

    # Check if cows count matches
    if cow_count != cows:
        return False

    return True

