import sys
from collections import defaultdict

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx])
    idx += 1
    m = int(data[idx])
    idx += 1

    # Group strings by length
    strings_by_length = defaultdict(list)

    for _ in range(n):
        length = int(data[idx])
        idx += 1
        strings_by_length[length].append(data[idx])
        idx += 1

    output = []

    for _ in range(m):
        length = int(data[idx])
        idx += 1
        query = data[idx]
        idx += 1

        # Check strings of the same length
        if length in strings_by_length:
            found = False
            for stored in strings_by_length[length]:
                diff_count = 0
                for c1, c2 in zip(query, stored):
                    if c1 != c2:
                        diff_count += 1
                        if diff_count > 1:
                            break
                if diff_count == 1:
                    found = True
                    break

            if found:
                output.append("YES")
            else:
                output.append("NO")
        else:
            output.append("NO")

    sys.stdout.write("\n".join(output))

if __name__ == "__main__":
    solve()
"}

