# Prime factorization of k
def prime_factors(x):
    factors = {}
    i = 2
    while i * i <= x:
        while x % i == 0:
            factors[i] = factors.get(i, 0) + 1
            x //= i
        i += 1
    if x > 1:
        factors[x] = factors.get(x, 0) + 1
    return factors

factors = prime_factors(k)

# For each card, compute its prime factor counts
prime_counts = []
for num in a:
    cnt = {}
    for p, _ in factors.items():
        cnt[p] = 0
    temp = num
    for p, _ in factors.items():
        while temp % p == 0:
            cnt[p] += 1
            temp //= p
    prime_counts.append(cnt)

# Use sliding window to count valid subarrays
valid = {p: 0 for p in factors}
answer = 0

l = 0
for r in range(n):
    # Add the current card to the window
    for p in factors:
        valid[p] += prime_counts[r][p]

    # Try to move l forward as long as we have enough factors
    while all(valid[p] >= factors[p] for p in factors):
        answer += n - r
        # Move l forward
        for p in factors:
            valid[p] -= prime_counts[l][p]
        l += 1

print(answer)
