def is_palindrome(s, l, r):
    """Check if substring s[l:r+1] is a palindrome"""
    while l < r:
        if s[l] != s[r]:
            return False
        l += 1
        r -= 1
    return True

s = input().strip()
n = len(s)
q = int(input())
queries = [tuple(map(int, input().split())) for _ in range(q)]

# Precompute palindrome array
pal = [[False] * n for _ in range(n)]
for i in range(n):
    for j in range(i, n):
        if s[i] == s[j]:
            if i + 1 > j - 1 or is_palindrome(s, i + 1, j - 1):
                pal[i][j] = True

# Create prefix sum array
prefix = [[0] * (n + 1) for _ in range(n)]
for i in range(n):
    cnt = 0
    for j in range(i, n):
        if pal[i][j]:
            cnt += 1
        prefix[i][j + 1] = cnt

# Answer queries
answers = []
for l, r in queries:
    # Convert to 0-indexed
    l -= 1
    r -= 1
    # Count palindromic substrings in [l, r]
    count = 0
    for i in range(l, r + 1):
        for j in range(i, r + 1):
            if pal[i][j]:
                count += 1
    answers.append(str(count))

print(' '.join(answers))
