def solve():
    n, s, k = map(int, input().split())
    r = list(map(int, input().split()))
    c = input().strip()

    # dp[pos][eaten][last_box][last_color] = minimum time
    # pos: current position (1-indexed)
    # eaten: number of candies eaten
    # last_box: index of last eaten box (or -1 if none)
    # last_color: color of last eaten box ('R', 'G', 'B')
    INF = float('inf')
    dp = {}

    # Initialize: at position s with 0 candies eaten, no last box
    dp[(s, 0, -1, 'None')] = 0

    for state, time in dp.items():
        pos, eaten, last_box, last_color = state

        # Try moving left
        if pos > 1:
            new_state = (pos-1, eaten, last_box, last_color)
            if new_state not in dp or dp[new_state] > time + 1:
                dp[new_state] = time + 1

        # Try moving right
        if pos < n:
            new_state = (pos+1, eaten, last_box, last_color)
            if new_state not in dp or dp[new_state] > time + 1:
                dp[new_state] = time + 1

        # Try eating candies if we haven't eaten any yet
        if eaten == 0:
            # No restriction
            new_state = (pos, eaten + r[pos-1], pos, c[pos-1])
            if new_state not in dp or dp[new_state] > time:
                dp[new_state] = time
        else:
            # Check restrictions
            if c[pos-1] != last_color and r[pos-1] > r[last_box-1]:
                new_state = (pos, eaten + r[pos-1], pos, c[pos-1])
                if new_state not in dp or dp[new_state] > time:
                    dp[new_state] = time

    # Find minimum time to eat at least k candies
    min_time = INF
    for state, time in dp.items():
        if state[1] >= k:
            min_time = min(min_time, time)

    if min_time == INF:
        print(-1)
    else:
        print(min_time)

solve()
