{"code": "
def construct_matrix(n):
    matrix = [[0] * n for _ in range(n)]
    half = n // 2

    # First half (0 to half-1): values increase then decrease
    for i in range(half):
        for j in range(half):
            if i == j:
                continue
            if j < i:
                matrix[i][j] = n - i - j
            else:
                matrix[i][j] = i + j
        # Add the symmetric part
