import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    total = sum(a)

    if total % 2 != 0:
        print("NO")
        return

    if n == 2:
        print("YES")
        return

