import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    moods = list(data[1:])

    # Try each possible number of vertices k (3 to n)
    for k in range(3, n + 1):
        # Check if n is divisible by k
        if n % k != 0:
            continue

        step = n // k

        # Check all possible starting positions
        found = False
        for start in range(k):
            all_good = True
            for i in range(k):
                pos = (start + i * step) % n
                if moods[pos] != '1':
                    all_good = False
                    break
            if all_good:
                found = True
                break

        if found:
            print("YES")
            return

    print("NO")

if __name__ == "__main__":
    solve()
