import sys
import math
from array import array

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    t = int(next(it))
    out_lines = []

    max_a = 1
    a_list = []
    for _ in range(t):
        n = int(next(it))
        k = int(next(it))
        a = [int(next(it)) for _ in range(n)]
        a_list.extend(a)
        max_a = max(max_a, max(a))

    # Sieve of smallest prime factor up to max_a
    max_a = max_a
    spf = array('i', [0] * (max_a + 1))
    is_prime = [True] * (max_a + 1)
    for i in range(2, int(math.isqrt(max_a)) + 1):
        if is_prime[i]:
            for j in range(i * i, max_a + 1, i):
                if is_prime[j]:
                    is_prime[j] = False
                    spf[j] = i
    for i in range(2, max_a + 1):
        if is_prime[i]:
            spf[i] = i

    def square_free(x: int) -> int:
        if x == 0:
            return 0
        res = 1
        while x > 1:
            p = spf[x]
            cnt = 0
            while x % p == 0:
                x //= p
                cnt += 1
            if cnt % 2 == 1:
                res *= p
        return res

    # Process each test case
    out_lines = []
    it = iter(data)
    t = int(next(it))
    for _ in range(t):
        n = int(next(it))
        k = int(next(it))
        a = [int(next(it)) for _ in range(n)]
        seen = set()
        segments = 1
        for num in a:
            sf = square_free(num)
            if sf in seen:
                segments += 1
                seen = {sf}
            else:
                seen.add(sf)
        out_lines.append(str(segments))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
