            is_covered = False
            for j in range(base, power):
                if power % j == 0:
                    is_covered = True
                    break

            if not is_covered:
                questions.add(power)

    # Print
    questions = sorted(questions)
    print(len(questions))
    print(' '.join(map(str, questions)))

solve()
