def solve():
    n = int(sys.stdin.readline())

    # We need to ask about all prime numbers
    # And all prime powers (like 4 = 2^2) that are not already covered by smaller numbers

    questions = set()

    # Start from the largest and work our way down
    for i in range(n, 1, -1):
        # Check if i is a prime power
        prime = None
        for j in range(2, i + 1):
            if i % j == 0:
                prime = j
                break

        # Check if all prime factors are the same
        is_prime_power = True
        for j in range(i + 1, n + 1):
            if j % i == 0:
                # Check if i divides a smaller prime
                prime_factors = set()
                for k in range(2, prime + 1):
                    if j % k == 0:
