import sys

def clean_string(s):
    n = len(s)
    # We'll build the result from the right
    result = []

    # Process from right to left
    for i in range(n-1, -1, -1):
        if i == n-1:
            # First character, just add
            result.append(s[i])
        else:
            # Check if we have "10" at positions i and i+1
            if s[i] == '1' and s[i+1] == '0':
                # We have "10", we can erase the '1'
                # This gives us '0' (the right character)
                # So we keep the '0' and skip the '1'
                # Just add the '0' (from position i+1)
                result.append('0')
            else:
                result.append(s[i])

    # Convert to string and return
    return ''.join(result)

def main():
    input = sys.stdin.read().split()
    if not input:
        return

    data = input[0:2*len(input)//2 + 1]

    t = int(data[0])
    idx = 1

    for _ in range(t):
        n = int(data[idx])
        s = data[idx + 1]
        idx += 2

        clean = clean_string(s)
        print(clean)

if __name__ == '__main__':
    main()
