import sys

def is_subsequence(s, t):
    """Check if s is a subsequence of t"""
    it = iter(t)
    return all(c in it for c in s)

def solve():
    data = sys.stdin.read().strip().split('\n')
    q = int(data[0])
    index = 1

    for _ in range(q):
        s = data[index]
        t = data[index + 1]
        p = data[index + 2]
        index += 3

        # Check if s is a subsequence of t
        if not is_subsequence(s, t):
            print("NO")
            continue

        # Check if we have enough characters in s + p to form t
        s_count = {}
        t_count = {}

        for c in s + p:
            s_count[c] = s_count.get(c, 0) + 1

        for c in t:
            t_count[c] = t_count.get(c, 0) + 1

        # Check if s_count has at least as many of each character as t_count
        possible = True
        for c, need in t_count.items():
            have = s_count.get(c, 0)
            if have < need:
                possible = False
                break

        print("YES" if possible else "NO")

if __name__ == "__main__":
    solve()
