import sys
from itertools import permutations

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    g = []
    idx = 0
    for _ in range(5):
        g.append([int(data[idx + j]) for j in range(5)])
        idx += 5

    max_total = 0

    # Brute-force all permutations of 5 elements
    for perm in permutations(range(1, 6)):
        # Initialize count for ordered pairs (i,j)
        count = [[0] * 6 for _ in range(6)]  # 1..5
        line = list(perm)

        # Process each step: first person enters, remaining talk
        for k in range(1, 6):
            # After k-th person enters, line is line[k-1:] (k=1: first enters, line[1:])
            # For step k (1-indexed), k=1 means first person just entered, remaining start at index 1 (0-based)
            remaining = line[k-1:]
            n_remaining = len(remaining)

            # Count pairs: i-th remaining (0-indexed) talks with i+1-th if even
            for i in range(0, n_remaining, 2):
                if i + 1 < n_remaining:
                    a = remaining[i]
                    b = remaining[i+1]
                    count[a][b] += 1
                    count[b][a] += 1

        # Calculate total happiness
        total = 0
        for i in range(1, 6):
            for j in range(1, 6):
                if i != j:
                    total += (g[i-1][j-1] + g[j-1][i-1]) * count[i][j]

        if total > max_total:
            max_total = total

    print(max_total)

if __name__ == "__main__":
    main()
