def solve():
    import sys
    data = sys.stdin.read().split()
    it = iter(data)

    t = int(next(it))

    results = []

    for _ in range(t):
        n = int(next(it))
        q = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # Precompute sorted array
        sorted_a = sorted(a)

        def dfs(low, high, target):
            # If target is zero, we can always achieve it (empty array)
            if target == 0:
                return True

            # If target exceeds the sum of the current range, impossible
            if target > prefix[high + 1] - prefix[low]:
                return False

            current_min = sorted_a[low]
            current_max = sorted_a[high]
            mid_value = (current_min + current_max) // 2

            # Find first index > mid_value (partition boundary)
            left_bound = low
            while left_bound <= high and sorted_a[left_bound] <= mid_value:
                left_bound += 1

            left_sum = prefix[left_bound] - prefix[low]
            right_sum = prefix[high + 1] - prefix[left_bound]

            if left_sum == target or right_sum == target:
                return True

            # If target is less than both, impossible
            if left_sum < target < right_sum:
                return False

            # Otherwise, recursively check both partitions
            return dfs(low, left_bound - 1, target) or dfs(left_bound, high, target)

        # Precompute prefix sums
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + sorted_a[i]

        for __ in range(q):
            s = int(next(it))

            if dfs(0, n - 1, s):
                results.append("Yes")
            else:
                results.append("No")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
