def is_valid(matrix, n):
    # Check if (1, 1) has a 1
    if matrix[0][0] == '1':
        return False

    # Check if (1, 1) has a 1 again
    if matrix[0][0] == '1':
        return False

    for i in range(n):
        for j in range(n):
            if matrix[i][j] == '1':
                # Check if it's the top-left corner
                if i == 0 and j == 0:
                    return False

