import sys

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        n = int(sys.stdin.readline())
        a = list(map(int, sys.stdin.readline().split()))

        # Sort the array
        a.sort()

        # Try to find a starting x and sequence of operations
        # We'll try all possible starting pairs (first operation)
        # For each pair, we'll recursively check if the rest can be destroyed

        result = None
        operations = []

        def dfs(current_x, used_indices, ops):
            # If no more elements, we're done
            if len(used_indices) == len(a):
                return True, ops

            # Try to find two elements that sum to current_x
            # Try all possible pairs of unused indices
            for i in range(len(a)):
                if i in used_indices:
                    continue

                for j in range(i + 1, len(a)):
                    if j in used_indices:
                        continue

                    if a[i] + a[j] == current_x:
                        # Try removing these two
                        new_used = used_indices.copy()
                        new_used.add(i)
                        new_used.add(j)
                        new_ops = ops.copy()
                        new_ops.append((a[i], a[j]))

                        # Update x to be the max of the two removed
                        new_x = max(a[i], a[j])

                        # Recursively check if the rest can be destroyed
                        success, ops_result = dfs(new_x, new_used, new_ops)
                        if success:
                            return True, ops_result

            return False, []

        # Try all possible pairs as the first operation
        for i in range(len(a)):
            for j in range(i + 1, len(a)):
                # Start with x = a[i] + a[j]
                success, ops = dfs(a[i] + a[j], set([i, j]), [(a[i], a[j])])
                if success:
                    result = success
                    operations = ops
                    break
            if result:
                break

        if result:
            print("YES")
            print(operations[0][0] + operations[0][1])
            for op in operations:
                print(f"{op[0]} {op[1]}")
        else:
            print("NO")

solve()
