def solve():
    n, m, k = map(int, input().split())
    board = []
    for _ in range(n):
        row = list(map(int, input().strip()))
        board.append(row)

    # We need to find maximum peas that is divisible by k+1
    # Let's work from bottom to top using dynamic programming
    # dp[i][col] = (max peas, move sequence) when starting at (i, col)
    # From (i, col) we can go to:
    # - (i+1, col-1) with move 'L'
    # - (i+1, col+1) with move 'R'

    dp = [[None] * m for _ in range(n)]  # dp[row][col] = (max_peas, moves)

    # Base case: starting from bottom row (n-1 in 0-indexed)
    for col in range(m):
        peas = board[n-1][col]
        # From (n-1, col), we can only move up
        dp[n-1][col] = (peas, ")

    # Work from bottom up
    for row in range(n-2, -1, -1):
        for col in range(m):
            max_peas = -1
            best_moves = ""

            # From (row, col), we can reach (row+1, col-1) with 'L'
            if col - 1 >= 0:
                peas, moves = dp[row+1][col-1]
                if peas != -1:
                    peas += board[row][col]
                    if peas % (k+1) == 0:
                        if peas > max_peas or (peas == max_peas and moves):
                            max_peas = peas
                            best_moves = 'L' + moves

            # From (row, col), we can reach (row+1, col+1) with 'R'
            if col + 1 < m:
                peas, moves = dp[row+1][col+1]
                if peas != -1:
                    peas += board[row][col]
