# Query ? 1 i for i from 2 to n
# The smallest value among these results will be the smallest element

min_val = float('inf')
smallest_index = 0

for i in range(1, n):
    res = query(1, i + 1)
    if res < min_val:
        min_val = res
        smallest_index = i

# Now we know the smallest element
