import sys
from collections import Counter
from itertools import combinations

def count_substrings(s):
    """Count occurrences of all substrings"""
    n = len(s)
    counter = Counter()
    for i in range(n):
        for j in range(i, n):
            substr = s[i:j+1]
            counter[substr] += 1
    return counter

def is_good_string(s, given_set):
    """Check if all given strings are most frequent substrings"""
    substr_counter = count_substrings(s)
    for substr in given_set:
        if substr not in substr_counter:
            return False
        if substr_counter[substr] < max(substr_counter.values()):
            return False
    return True

def find_good_string(given_set):
    """Find the shortest good string"""
    # Get all unique characters
    chars = set()
    for s in given_set:
        for c in s:
            chars.add(c)
    chars = sorted(chars)  # Lexicographically smallest

    # Try all possible permutations of characters
    from itertools import permutations
    for perm_len in range(1, len(chars) + 1):
        for perm in permutations(chars, perm_len):
            candidate = ''.join(perm)
            if is_good_string(candidate, given_set):
