                row = quad_row + i
                col = quad_col + j
                if (row + col) % 2 == 0:
                    target = 1 if start_black else 0
                else:
                    target = 0 if start_black else 1
                # piece[i][j] is 1 for black, 0 for white
                if int(piece[i][j]) != target:
                    cost += 1
        return cost

    min_cost = float('inf')
    # Try each piece in each quadrant
    for piece_idx in range(4):
        for quad_row in [0, n]:
            for quad_col in [0, n]:
