                for start_black in [True, False]:
                    # Assign the current piece to this quadrant
                    # Calculate cost for other pieces in other quadrants
                    other_pieces = [pieces[p] for p in range(4) if p != piece_idx]

                    # Try all combinations of patterns for other pieces
                    for other_patterns in product([True, False], repeat=len(other_pieces)):
                        total_cost = 0

                        # Assign current piece
                        total_cost += get_cost(pieces[piece_idx], quad_row, quad_col, start_black)

                        # Assign other pieces
                        for other_idx, other_pattern in enumerate(other_patterns):
