def solve():
    a1, a2, a3, a4 = map(int, input().split())

    # Calculate the number of 4s and 7s that are not part of transitions
    x = a1 - a3  # 4s that are not part of "47" substrings
    y = a2 - a4  # 7s that are not part of "74" substrings

    # Check if we have enough digits
    if x < 0 or y < 0:
        print(-1)
        return

    # Check if transitions are possible
    # For there to be a3 4-to-7 transitions and a4 7-to-4 transitions,
    # we need at least max(a3, a4) digits of each type to create blocks
    if max(a3, a4) > max(x, y):
        print(-1)
        return

    # Check if transitions can happen
    # If a3 == a4, we need at least one more digit of the starting type
    # If a3 == a4 + 1, we start with 4 and end with 7
    # If a4 == a3 + 1, we start with 7 and end with 4

    if abs(a3 - a4) > 1:
        print(-1)
        return

    # Start with 4 if possible (to get lexicographically smaller)
    if a3 == a4 and max(x, y) == x and x > y:
        # Start with 4 and end with 4
        result = []
        for i in range(a3 + 1):
            if i % 2 == 0:
                # Even-indexed blocks (0, 2, ...) start with 4
                # Distribute remaining 4s evenly
                result.append('4' * ((x - a3) // (a3 + 1) + 1))
            else:
                # Odd-indexed blocks start with 7
                # Distribute remaining 7s evenly
                result.append('7' * ((y - a4) // (a3 + 1) + 1))

        # Join and print
        print(''.join(result))
    elif a3 == a4 + 1 and max(x, y) == y and y > x:
        # Start with 4 and end with 7
        result = []
        for i in range(a3 + 1):
            if i % 2 == 0:
                result.append('4' * ((x - a3) // (a3 + 1) + 1))
            else:
                result.append('7' * ((y - a4) // (a3 + 1) + 1))

        print(''.join(result))
