import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    freq = {}
    for num in a:
        freq[num] = freq.get(num, 0) + 1

    values = sorted(freq.keys())

    m = len(values)

    # DP
    dp = [0] * (m + 1)

    for i in range(1, m + 1):
        val = values[i - 1]
        cnt = freq[val]
        dp[i] = max(dp[i - 1], dp[i - 2] + cnt * val)

    print(dp[m])

if __name__ == "__main__":
    solve()
