s = input().strip()
t = input().strip()

# Check if t is a subsequence of s (can delete to get t)
def is_subsequence(s, t):
    it = iter(s)
    return all(c in it for c in t)

# Check if t is a permutation of s (can swap to get t)
def is_permutation(s, t):
    return sorted(s) == sorted(t)

# Check if s has enough of each character to form t
def has_enough_chars(s, t):
    from collections import Counter
    return all(count >= t_count for s_count, t_count in zip(Counter(s).values(), Counter(t).values()))

# Check if we need both operations
# We need both if:
# 1. We can't just delete (t is not a subsequence)
# 2. We can't just swap (t is not a permutation)
# 3. AND we have enough characters in s to form t
# 4. AND s is longer than t (we need to delete)

def needs_both(s, t):
    return not is_subsequence(s, t) and not is_permutation(s, t) and has_enough_chars(s, t) and len(s) > len(t)

if is_subsequence(s, t) and not is_permutation(s, t):
    print("automaton")
elif is_permutation(s, t) and not is_subsequence(s, t):
    print("array")
elif needs_both(s, t):
    print("both")
else:
    print("need tree")
