def is_possible_to_zero_array(n, a):
    """Check if we can make all elements zero with the given operation."""
    total_sum = sum(a)

    # If sum is odd, it's impossible to make all zero
    if total_sum % 2 != 0:
        return False

    # If maximum element is greater than half the total sum, impossible
    max_element = max(a)
    if max_element > total_sum // 2:
        return False

    return True

