import sys

def can_place_seals(seal1, seal2, a, b):
    """Check if two seals can be placed without overlapping"""

    # Check if both seals fit individually
    if (seal1[0] > a or seal1[1] > b) or (seal2[0] > a or seal2[1] > b):
        return False

    # Try side by side horizontally
    if (seal1[0] + seal2[0] <= a) and (max(seal1[1], seal2[1]) <= b):
        return True

    # Try side by side vertically
    if (seal1[1] + seal2[1] <= b) and (max(seal1[0], seal2[0]) <= a):
        return True

    return False

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = int(data[1])
    b = int(data[2])

    seals = []
    index = 3
    for i in range(n):
        x = int(data[index])
        y = int(data[index + 1])
        seals.append((x, y))
        index += 2

    max_area = 0

    # Try all pairs of seals
    for i in range(n):
        for j in range(i + 1, n):
            seal1 = seals[i]
            seal2 = seals[j]

            # Try all combinations of orientations
            for w1, h1 in [(seal1[0], seal1[1]), (seal1[1], seal1[0])]:
                for w2, h2 in [(seal2[0], seal2[1]), (seal2[1], seal2[0])]:
                    if can_place_seals((w1, h1), (w2, h2), a, b):
                        area = w1 * h1 + w2 * h2
                        max_area = max(max_area, area)

    print(max_area)

if __name__ == "__main__":
    solve()
